<?php $view->extend('layouts.admin');$view->section('content');?><div class="aho-admin-page"><div class="aho-admin-page__header"><div><h1>📱 Mobile Build İşleri</h1><p>APK, AAB, PWA ve kaynak kod build süreçlerini izleyin.</p></div><button class="aho-btn aho-btn--outline" type="button" id="mobileWorkerHealth">Worker bağlantısını test et</button> <button class="aho-btn aho-btn--outline" type="button" id="mobileGithubHealth">GitHub Actions kontrol et</button></div><div id="mobileWorkerHealthResult" style="margin-bottom:14px"></div><script>document.getElementById('mobileWorkerHealth').addEventListener('click',async()=>{const b=document.getElementById('mobileWorkerHealth');const r=document.getElementById('mobileWorkerHealthResult');b.disabled=true;b.textContent='Kontrol ediliyor...';try{const x=await fetch('/admin/mobile-buildler/worker-health');const d=await x.json();r.innerHTML='<div class="aho-alert '+(d.ok?'aho-alert--success':'aho-alert--danger')+'">'+(d.ok?'✓ Worker bağlantısı başarılı':'✗ '+(d.error||'Worker bağlantısı başarısız') )+'</div>';}catch(e){r.innerHTML='<div class="aho-alert aho-alert--danger">Worker kontrolü başarısız.</div>';}b.disabled=false;b.textContent='Worker bağlantısını test et';});document.getElementById('mobileGithubHealth').addEventListener('click',async()=>{const r=document.getElementById('mobileWorkerHealthResult');try{const x=await fetch('/admin/mobile-buildler/github-health');const d=await x.json();r.innerHTML='<div class="aho-alert '+(d.ok?'aho-alert--success':'aho-alert--danger')+'">'+(d.ok?'✓ GitHub Actions bağlantısı başarılı':'✗ '+(d.error||'GitHub ayarları eksik'))+'</div>';}catch(e){r.innerHTML='<div class="aho-alert aho-alert--danger">GitHub kontrolü başarısız.</div>';}});</script><div class="aho-card" style="padding:0;overflow:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th style="padding:12px;text-align:left">#</th><th style="padding:12px">Proje</th><th style="padding:12px">Müşteri</th><th style="padding:12px">Tür</th><th style="padding:12px">Durum</th><th style="padding:12px">İlerleme</th><th style="padding:12px">Tarih</th></tr></thead><tbody><?php foreach($jobs as $job):?><tr data-admin-mobile-job="<?= (int)$job['id']?>" style="border-top:1px solid var(--aho-color-border)"><td style="padding:12px">#<?= (int)$job['id']?></td><td style="padding:12px"><?=e($job['project_name']??'-')?></td><td style="padding:12px"><?=e($job['email']??'-')?></td><td style="padding:12px"><?=e(strtoupper($job['build_type']))?></td><td style="padding:12px"><?=e($job['status'])?></td><td style="padding:12px">%<?= (int)$job['progress']?></td><td style="padding:12px"><?=e($job['created_at']??'')?></td><td style="padding:12px"><?php if(in_array($job['status'],['failed','waiting_worker'],true)):?><form method="post" action="/admin/mobile-buildler/<?= (int)$job['id']?>/tekrar"><?=csrf()?><button class="aho-btn aho-btn--sm">Tekrar çalıştır</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if(!$jobs):?><div style="padding:40px;text-align:center">Henüz Mobile Build işi yok.</div><?php endif;?></div></div><script>setInterval(()=>{document.querySelectorAll('[data-admin-mobile-job]').forEach(async row=>{try{const r=await fetch('/admin/mobile-buildler/'+row.dataset.adminMobileJob+'/status');const d=await r.json();if(d.ok){if(row.children[4])row.children[4].textContent=d.job.status;if(row.children[5])row.children[5].textContent='%'+d.job.progress;}}catch(e){}})},30000);</script><?php $view->endSection();?>